window.__execAttack = (id) => { try { executeAttack(id); } catch (e) { console.error(e); } };
window.__tryAbility = () => { try { tryAbility(); } catch (e) { console.error(e); } };
window.__tryParry = () => { try { tryParry(); } catch (e) { console.error(e); } };

